import sys
def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0]); pos = 1; out = []
    for _ in range(t):
        n = int(data[pos]); pos += 1
        cnt = [0] * (n + 1)
        for i in range(1, n + 1):
            b = int(data[pos]); pos += 1
            if b != i:
                cnt[b] += 1
        best = 0; who = 0; tie = False
        for s in range(1, n + 1):
            if cnt[s] > best:
                best = cnt[s]; who = s; tie = False
            elif cnt[s] == best and best > 0:
                tie = True
        out.append("0" if best == 0 or tie else str(who))
    print("\n".join(out))
main()
